// Synthetic catalogue profiles (CL §8 "one generator, two sizes"; PLAN C5: each profile declares its calendar range
// before generation, so the synthetic eval cutoff = 80% of that range without inspecting data).
//
// demo: ~400 items, 6 categories, ~40k reviews (generated in the worker on Load sample).
// eval: 900 items, 6 categories, ~90k reviews (generated by scripts/eval.ts at run time; never committed).
//       DEVIATION from CL §8's "default 600 items": with a 70/30 item split, 600 items give an expected 30 held-out
//       items per category — the support gate itself — so about half the categories would miss it by chance, and
//       ~180 held-out items cannot reliably yield >= 120 items with >= 20 post-cutoff reviews. 900 items give an
//       expected 45 per category and ~270 held-out items. Recorded in docs/DEFERRED-VALIDATION.md; the support counts
//       are only known after the first --final run (D6).
//
// All numbers are synthetic design choices, not measurements.

export type ProfileId = 'demo' | 'eval';

export interface CategorySpec {
  /** Category name as it appears in the data. */
  name: string;
  /** Mean of the latent item quality q (stars) — different per category so category priors matter. */
  baseline: number;
  /** SD of the latent item quality around the baseline. */
  spread: number;
  /** Probability a review is verified. */
  verifiedShare: number;
}

export interface CountSchedule {
  /** Share of items that are sparse (1..sparseMax reviews): cold-start and insufficient items. */
  sparseShare: number;
  sparseMax: number;
  /** Pareto scale and shape for the remaining items (heavy tail). */
  paretoScale: number;
  paretoShape: number;
  /** Hard cap per item. */
  maxCount: number;
}

export interface SynthProfile {
  id: ProfileId;
  itemCount: number;
  categories: readonly CategorySpec[];
  /** Declared calendar range [start, end) in epoch ms; every generated timestamp lies inside it. */
  calendar: { start: number; end: number };
  /** Fixed reference time; equals calendar.end so no review is "future". */
  asOf: number;
  /** Items launch uniformly within the first launchMaxFraction of the calendar (sparse items: up to 0.95). */
  launchMaxFraction: number;
  /** Share of non-sparse items with a quality change point (drift items, truth per period). */
  driftShare: number;
  /** Size of the drift step in stars (direction from the item id). */
  driftStep: number;
  counts: CountSchedule;
  /** SD of the discretised rating kernel around q (CL: explicit per-item categorical distribution). */
  ratingKernelSd: number;
  /** Relative review intensity by UTC weekday, index 0 = Sunday. */
  weekdayWeights: readonly number[];
  defaultSeed: number;
  /** Whether the sample builder adds the code-built trap categories. */
  includeTraps: boolean;
}

const CATEGORIES: readonly CategorySpec[] = [
  { name: 'books', baseline: 4.3, spread: 0.35, verifiedShare: 0.8 },
  { name: 'electronics', baseline: 3.9, spread: 0.5, verifiedShare: 0.85 },
  { name: 'kitchen', baseline: 4.1, spread: 0.4, verifiedShare: 0.75 },
  { name: 'toys', baseline: 3.8, spread: 0.55, verifiedShare: 0.7 },
  { name: 'beauty', baseline: 3.6, spread: 0.6, verifiedShare: 0.65 },
  { name: 'garden', baseline: 4.0, spread: 0.45, verifiedShare: 0.8 },
];

const COUNTS: CountSchedule = {
  sparseShare: 0.2,
  sparseMax: 15,
  paretoScale: 55,
  paretoShape: 1.8,
  maxCount: 2000,
};

/** Weekend-heavy shopping pattern (Sun, Mon, ..., Sat). */
const WEEKDAY_WEIGHTS: readonly number[] = [1.3, 0.9, 0.9, 0.95, 1.0, 1.1, 1.3];

const DEMO_START = Date.UTC(2023, 0, 1);
const EVAL_START = Date.UTC(2022, 0, 1);
const END = Date.UTC(2025, 0, 1);

export const PROFILES: Readonly<Record<ProfileId, SynthProfile>> = {
  demo: {
    id: 'demo',
    itemCount: 400,
    categories: CATEGORIES,
    calendar: { start: DEMO_START, end: END },
    asOf: END,
    launchMaxFraction: 0.6,
    driftShare: 0.05,
    driftStep: 1.0,
    counts: COUNTS,
    ratingKernelSd: 0.9,
    weekdayWeights: WEEKDAY_WEIGHTS,
    defaultSeed: 33,
    includeTraps: true,
  },
  eval: {
    id: 'eval',
    itemCount: 900,
    categories: CATEGORIES,
    calendar: { start: EVAL_START, end: END },
    asOf: END,
    launchMaxFraction: 0.6,
    driftShare: 0.05,
    driftStep: 1.0,
    counts: COUNTS,
    ratingKernelSd: 0.9,
    weekdayWeights: WEEKDAY_WEIGHTS,
    defaultSeed: 33,
    includeTraps: false,
  },
};

export function getProfile(id: ProfileId): SynthProfile {
  return PROFILES[id];
}
